using Aspire.Hosting.Testing;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Xunit;

namespace MyApp.AppHost.Tests;

/// <summary>
/// Evaluation harness that starts the distributed application and runs
/// evaluation scenarios defined in evaluation.yml against it.
/// </summary>
public class EvaluationHarness : IAsyncLifetime
{
    private DistributedApplication? _app;

    public async Task InitializeAsync()
    {
        var builder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        builder.Services.AddLogging(logging =>
        {
            logging.SetMinimumLevel(LogLevel.Information);
        });

        _app = await builder.BuildAsync();
        await _app.StartAsync();
    }

    public async Task DisposeAsync()
    {
        if (_app is not null)
        {
            await _app.DisposeAsync();
        }
    }

    [Fact]
    public async Task AppHost_StartsSuccessfully()
    {
        Assert.NotNull(_app);

        // Verify the application model is available and the app started without error.
        var model = _app.Services.GetRequiredService<Aspire.Hosting.DistributedApplicationModel>();
        Assert.NotNull(model);
    }

    [Fact]
    public async Task AppHost_AllResourcesReachRunningState()
    {
        Assert.NotNull(_app);

        var rns = _app.Services.GetRequiredService<Microsoft.Extensions.Hosting.IHostApplicationLifetime>();
        Assert.False(rns.ApplicationStopping.IsCancellationRequested,
            "Application should not be stopping immediately after start.");
    }
}

